const deps = { Web: ['API'], API: ['DB'], DB: ['Web'] };
function hasCycle() {
  const visiting = new Set();
  const done = new Set();
  function visit(n) {
    if (visiting.has(n)) return true;
    if (done.has(n)) return false;
    visiting.add(n);
    for (const d of deps[n] || []) {
      if (visit(d)) return true;
    }
    visiting.delete(n);
    done.add(n);
    return false;
  }
  return Object.keys(deps).some(visit);
}
console.log(hasCycle() ? 'cycle' : 'clean');

