function checkERD(entities, rels) {
  for (const r of rels) {
    if (!entities.includes(r.from)) return 'unknown entity: ' + r.from;
    if (!entities.includes(r.to)) return 'unknown entity: ' + r.to;
    if (!r.cardinality) return 'missing cardinality';
  }
  return 'ok';
}
console.log(checkERD(['Customer', 'Order'], [{ from: 'Customer', to: 'Order', cardinality: '1:N' }]));

